/** Tramos fijos: si la distancia es menor o igual a `hastaKm`, se cobra `precio`. */
export const LOWCOST_TRAMOS = [
  { hastaKm: 3, precio: 3000 },
  { hastaKm: 5, precio: 4000 },
  { hastaKm: 7, precio: 5300 },
  { hastaKm: 10, precio: 7000 },
] as const;

/** De 10 a 20 km se cobra por km entero (redondeado hacia arriba). */
export const LOWCOST_PRECIO_POR_KM = 700;

/** Más allá de esta distancia no hay precio automático: se consulta por WhatsApp. */
export const LOWCOST_MAX_KM = 20;

export type PrecioLowCost = number | 'consultar';

export function calcularPrecioLowCost(km: number): PrecioLowCost {
  // 1. Validar la entrada: nada de negativos, NaN ni Infinity.
  if (!Number.isFinite(km) || km < 0) {
    throw new RangeError(`Distancia inválida: ${km}. Tiene que ser un número >= 0.`);
  }

  // 2. Más de 20 km: no calculamos, se deriva a WhatsApp.
  if (km > LOWCOST_MAX_KM) {
    return 'consultar';
  }

  // 3. Hasta 10 km: buscamos el primer tramo que "contenga" la distancia.
  for (const tramo of LOWCOST_TRAMOS) {
    if (km <= tramo.hastaKm) {
      return tramo.precio;
    }
  }

  // 4. Entre 10 y 20 km: km redondeado hacia arriba Ã— $700.
  return Math.ceil(km) * LOWCOST_PRECIO_POR_KM;
}
```

