    });
  });

  describe('tramo por km (más de 10 y hasta 20 km)', () => {
    it.each([
      [10.1, 7700], // Math.ceil(10.1) = 11 → 11 × 700
      [12, 8400], // 12 × 700
      [15.4, 11200], // Math.ceil(15.4) = 16 → 16 × 700
      [20, 14000], // 20 km exactos todavía se calcula
    ])('%s km cuesta $%s', (km, esperado) => {
      expect(calcularPrecioLowCost(km)).toBe(esperado);
    });
  });

  describe('más de 20 km', () => {
    it('devuelve "consultar" para 20,1 km', () => {
      expect(calcularPrecioLowCost(20.1)).toBe('consultar');
    });

    it('devuelve "consultar" para distancias largas', () => {
      expect(calcularPrecioLowCost(45)).toBe('consultar');
    });
  });

  describe('entradas inválidas', () => {
    it.each([-1, Number.NaN, Number.POSITIVE_INFINITY])('rechaza %s', (km) => {
      expect(() => calcularPrecioLowCost(km)).toThrow(RangeError);
    });
  });
});
```

