1. La función (`lowcost.ts`)

/**
 * Tarifas LowCost 2026 (fuente: docs/contexto/precios.md).
 * Cada tramo dice "hasta cuántos km" y cuánto cuesta.
 * Están ordenados de menor a mayor: el orden importa (ver `find` abajo).
 */
export const LOW_COST_TRAMOS = [
  { hastaKm: 3, precio: 3000 },
  { hastaKm: 5, precio: 4000 },
  { hastaKm: 7, precio: 5300 },
  { hastaKm: 10, precio: 7000 },
] as const;
/** Pasados los 10 km se cobra por km (redondeado para arriba). */
export const LOW_COST_PRECIO_POR_KM = 700;
/** Más allá de esto no damos precio automático: se consulta por WhatsApp. */
export const LOW_COST_KM_MAXIMO = 20;
/** O un número (pesos) o el texto literal 'consultar'. */
export type PrecioLowCost = number | 'consultar';
/**
 * Calcula el precio de un envío LowCost según la distancia.
 *
 * @param km Distancia en kilómetros (puede tener decimales, ej. 10.3).
 * @returns Precio en ARS, o 'consultar' si supera los 20 km.
 * @throws RangeError si km es negativo, NaN o infinito.
 *
 * @example
 * calcularPrecioLowCost(2.5)  // 3000
 * calcularPrecioLowCost(10.3) // 7700  → Math.ceil(10.3) = 11 → 11 × 700
 * calcularPrecioLowCost(25)   // 'consultar'
 */
export function calcularPrecioLowCost(km: number): PrecioLowCost {
  // 1) Validar la entrada: primero descartar lo que no tiene sentido.
  if (!Number.isFinite(km) || km < 0) {
    throw new RangeError(`Distancia inválida: ${km}. Tiene que ser un número mayor o igual a 0.`);
  }
  // 2) Fuera de la zona operativa: no damos precio.
  if (km > LOW_COST_KM_MAXIMO) return 'consultar';
  // 3) Buscar el primer tramo fijo donde "entran" los km.
  const tramo = LOW_COST_TRAMOS.find((t) => km <= t.hastaKm);
  if (tramo) return tramo.precio;
  // 4) Si no entró en ningún tramo fijo, está entre 10 y 20 km: se cobra por km.
  return Math.ceil(km) * LOW_COST_PRECIO_POR_KM;
}
